+    let i = 0;
+    if (!started && chunk.length > 0) {
+      started = true;
+      if (chunk.charCodeAt(0) === 0xfeff) i = 1;
+    }
+    for (; i < chunk.length; i++) {
+      const ch = chunk[i];
+      const crlf = afterCR && ch === '\n';
+      afterCR = ch === '\r';
+      if (ch === '\r' || (ch === '\n' && !crlf)) line++;
