'use strict';
const assert = require('node:assert/strict');
const { createParser, parse } = require('./src/csv');

function allSplits(text, opts) {
  const whole = parse(text, opts);
  for (let a = 0; a <= text.length; a++) {
    for (let b = a; b <= text.length; b++) {
      const p = createParser(opts);
      const out = [];
      for (const c of [text.slice(0, a), '', text.slice(a, b), text.slice(b)]) out.push(...p.push(c));
      out.push(...p.end());
      assert.deepEqual(out, whole, JSON.stringify([text, a, b]));
    }
  }
  return whole;
}
const cases = [
  ['', []], ['\uFEFF', []], ['\n', [['']]], ['\n\n', [[''], ['']]], ['a\n', [['a']]],
  ['a\r\nb\rc\n', [['a'], ['b'], ['c']]], ['\r\r\n', [[''], ['']]],
  ['"a""b",c', [['a"b', 'c']]], ['"x\r\ny",z\r\n', [['x\r\ny', 'z']]],
  ['a"b"c,d', [['a"b"c', 'd']]], ['""', [['']]], [',', [['', '']]],
  ['\uFEFFa,\uFEFFb', [['a', '\uFEFFb']]], ['"""",""""""', [['"', '""']]],
  ['😀,"😀"\n', [['😀', '😀']]],
];
for (const [t, e] of cases) assert.deepEqual(allSplits(t), e, JSON.stringify(t));
assert.deepEqual(allSplits('a;b\n"c;d";e', { delimiter: ';' }), [['a', 'b'], ['c;d', 'e']]);

// incremental emission
let p = createParser();
assert.deepEqual(p.push('a\r'), [['a']]);
assert.deepEqual(p.push('\nb'), []);
assert.deepEqual(p.end(), [['b']]);
assert.deepEqual(p.end(), []);
assert.throws(() => p.push(''), e => e instanceof Error);
assert.throws(() => createParser().push(1), TypeError);
for (const d of ['"', '\r', '\n', '', ',,', 1, null]) assert.throws(() => createParser({ delimiter: d }), RangeError);

// line numbers
function syntaxLine(chunks) {
  const q = createParser();
  try { for (const c of chunks) q.push(c); q.end(); } catch (e) {
    assert.ok(e instanceof SyntaxError); return e.message.match(/line (\d+)/)[1];
  }
  assert.fail('no error');
}
assert.equal(syntaxLine(['"a\r', '\nb" x']), '2');
assert.equal(syntaxLine(['a\r\n"b\rc\nd"x']), '4');
assert.equal(syntaxLine(['a\n"b\r\n']), '3');
assert.equal(syntaxLine(['"a" ']), '1');

const objs = parse('x,x,x_2,x\n1,2\n', { header: true });
assert.deepEqual(objs, [{ x: '1', x_2: '2', x_2_2: '', x_3: '' }]);
const proto = parse('__proto__\nv', { header: true })[0];
assert.equal(Object.getPrototypeOf(proto), Object.prototype);
assert.deepEqual(Object.keys(proto), ['__proto__']);
assert.deepEqual(parse('', { header: true }), []);
console.log('smoke ok');
